package cn.zhuatech.audit.deep;import cn.zhuatech.audit.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/audit-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/engagements/{id}/approve")ApiResponse<?> approve(@PathVariable Long id){return ApiResponse.ok(s.approve(id));}@PostMapping("/workpapers/{id}/review")ApiResponse<?> review(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ReviewRequest r){return ApiResponse.ok(s.reviewPaper(id,r));}@PostMapping("/findings/{id}/verify")ApiResponse<?> verify(@PathVariable Long id,@Valid @RequestBody DeepDomainService.VerifyRequest r){return ApiResponse.ok(s.verify(id,r));}@PostMapping("/engagements/{id}/issue-report")ApiResponse<?> report(@PathVariable Long id){return ApiResponse.ok(s.issueReport(id));}@PostMapping("/engagements/{id}/close")ApiResponse<?> close(@PathVariable Long id){return ApiResponse.ok(s.close(id));}}
